parameters.jsCode:
// Step 3 & 4: Audit initial dossier against inferred requirements
const requestData = $('Step 1: Intake Webhook').first().json.body;
const requirements = JSON.parse($input.first().json.output || '[]');
const initialAttachments = requestData.initial_documents || [];

const items = [];
let verifiedCount = 0;
let criticalMissingCount = 0;

requirements.forEach(req => {
  const found = initialAttachments.some(doc => 
    doc.name.toLowerCase().includes(req.id.toLowerCase().replace(/_/g, ' ')) ||
    req.query_hints.some(hint => doc.name.toLowerCase().includes(hint.toLowerCase()))
  );

  if (found) {
    verifiedCount++;
    items.push({
      requirement_id: req.id,
      name: req.name,
      status: 'VERIFIED',
      source: 'INITIAL_ATTACHMENT'
    });
  } else {
    items.push({
      requirement_id: req.id,
      name: req.name,
      status: 'MISSING',
      importance: req.importance,
      query_hints: req.query_hints
    });
    if (req.importance === 'CRITICAL' || req.importance === 'MANDATORY') {
      criticalMissingCount++;
    }
  }
});

const isComplete = (criticalMissingCount === 0);
const completenessScore = Math.round((verifiedCount / requirements.length) * 100);

return [{
  json: {
    isComplete,
    completenessScore,
    requirementsCount: requirements.length,
    verifiedCount,
    criticalMissingCount,
    auditItems: items,
    missingRequirements: items.filter(i => i.status === 'MISSING')
  }
}];

